# এসএসসি সাধারণ গণিত অধ্যায় ৫ (এক চলকবিশিষ্ট সমীকরণ): সমন্বিত সৃজনশীল প্রশ্ন (৫.১ সরল + ৫.২ দ্বিঘাত), মধ্যম ৫টি; ক (২), খ (৪), গ (৪)
import json, os, sympy as sp
from sympy import Rational as R, sqrt
x,t,v=sp.symbols('x t v')
S_=lambda e,s=x: sorted(sp.solve(e,s))

# ---------- যাচাই ----------
assert S_(3*x+5-R(5,2)*(x+5))==[15] and 3*15==45 and S_((45-t)*(15-t)-351,t)==[6,54] and (45-6)*(15-6)==351 and 15-54<0
assert S_(2*(x+x+4)-40)==[8] and 8*12==96 and sp.sqrt(8**2+12**2)==4*sqrt(13) and round(float(4*sqrt(13)),2)==14.42 and S_((12+t)*(8+t)-165,t)==[-23,3] and 15*11==165
assert S_((x+1)-3*(x-1))==[2] and S_(t+1/t-R(5,2),t)==[R(1,2),2] and S_(x-2*(x-1))==[2] and S_(2*x-(x-1))==[-1] and all(sp.simplify((x/(x-1)+(x-1)/x).subs(x,r)-R(5,2))==0 for r in (2,-1)) and sp.expand((x-2)*(x+1))==x**2-x-2
assert S_((90-9*x)-(9*x+9)-27)==[3] and 10*6+3==63 and 10*3+6==36 and S_(x*(9-x)-18)==[3,6] and 63-36==27
assert S_(60/v+5-9,v)==[15] and S_(v**2+5*v-300,v)==[-20,15] and sp.simplify(60/v-60/(v+5)-1).subs(v,15)==0 and R(120,9)==R(40,3) and S_(60/v+5-8,v)==[20]

CQ=[
("বর্তমানে পিতার বয়স পুত্রের বয়সের 3 গুণ। 5 বছর পর পিতার বয়স পুত্রের বয়সের 2½ গুণ হবে।",
 ["পুত্রের বর্তমান বয়স x বছর ধরে একটি সমীকরণ গঠন কর।","পিতা ও পুত্রের বর্তমান বয়স নির্ণয় কর।","কত বছর আগে পিতা ও পুত্রের বয়সের গুণফল 351 ছিল?"],
 "ক) পিতার বয়স 3x বছর; 5 বছর পর: 3x + 5 = (5/2)(x + 5)\nখ) 6x + 10 = 5x + 25 ⇒ x = 15\nপুত্রের বয়স 15 বছর, পিতার বয়স 45 বছর\nগ) t বছর আগে: (45 − t)(15 − t) = 351\n⇒ 675 − 60t + t² = 351 ⇒ t² − 60t + 324 = 0 ⇒ (t − 6)(t − 54) = 0\nt = 54 হলে বয়স ঋণাত্মক হয় ⇒ t = 6\n∴ 6 বছর আগে (তখন বয়স 39 ও 9; 39 × 9 = 351 ✓)"),
("একটি আয়তাকার বাগানের দৈর্ঘ্য প্রস্থ অপেক্ষা 4 মিটার বেশি এবং বাগানটির পরিসীমা 40 মিটার।",
 ["প্রস্থ x মিটার ধরে পরিসীমার সাহায্যে একটি সমীকরণ গঠন কর।","বাগানটির দৈর্ঘ্য, প্রস্থ, ক্ষেত্রফল ও কর্ণের দৈর্ঘ্য নির্ণয় কর।","দৈর্ঘ্য ও প্রস্থ প্রত্যেকে সমান পরিমাণ বাড়ালে ক্ষেত্রফল 165 বর্গমিটার হয়। দৈর্ঘ্য ও প্রস্থ কত করে বাড়ানো হয়েছিল?"],
 "ক) দৈর্ঘ্য = (x + 4) মি ⇒ 2(x + x + 4) = 40\nখ) 4x + 8 = 40 ⇒ x = 8\nপ্রস্থ 8 মি, দৈর্ঘ্য 12 মি, ক্ষেত্রফল = 96 বর্গমি\nকর্ণ = √(12² + 8²) = √208 = 4√13 ≈ 14.42 মি\nগ) t মিটার বাড়ালে (12 + t)(8 + t) = 165\n⇒ t² + 20t + 96 = 165 ⇒ t² + 20t − 69 = 0 ⇒ (t + 23)(t − 3) = 0\nদৈর্ঘ্য ঋণাত্মক হয় না ⇒ t = 3 মিটার (15 × 11 = 165 ✓)"),
("দুইটি সমীকরণ: A: (x + 1)/(x − 1) = 3 এবং B: x/(x − 1) + (x − 1)/x = 5/2, যেখানে x ≠ 0, 1",
 ["A সমীকরণটি সমাধান কর।","B সমীকরণটি সমাধান করে সমাধান সেট নির্ণয় কর।","A ও B এর সমাধান সেটের সংযোগ ও ছেদ নির্ণয় কর এবং যে দ্বিঘাত সমীকরণের মূলদ্বয় B এর মূলদ্বয়, তা গঠন কর।"],
 "ক) x + 1 = 3(x − 1) ⇒ x + 1 = 3x − 3 ⇒ 2x = 4 ⇒ x = 2\nখ) x/(x − 1) = t ধরলে t + 1/t = 5/2 ⇒ 2t² − 5t + 2 = 0 ⇒ (2t − 1)(t − 2) = 0\nt = 2 ⇒ x = 2x − 2 ⇒ x = 2\nt = 1/2 ⇒ 2x = x − 1 ⇒ x = −1\nসমাধান সেট = {−1, 2}\nগ) A এর সমাধান সেট = {2}\nসংযোগ = {−1, 2}, ছেদ = {2}\nমূলদ্বয় 2 ও −1 ⇒ (x − 2)(x + 1) = 0 ⇒ x² − x − 2 = 0"),
("একটি দুই অঙ্কবিশিষ্ট সংখ্যার অঙ্কদ্বয়ের যোগফল 9। অঙ্কদ্বয় স্থান বিনিময় করলে যে সংখ্যা পাওয়া যায়, তা মূল সংখ্যা অপেক্ষা 27 কম।",
 ["একক স্থানীয় অঙ্ক x ধরে মূল সংখ্যা ও স্থান বিনিময়ের পর সংখ্যাটি x এর মাধ্যমে প্রকাশ কর।","সমীকরণ গঠন করে মূল সংখ্যাটি নির্ণয় কর।","অঙ্কদ্বয়ের যোগফল 9 এবং গুণফল 18 হলে সম্ভাব্য সংখ্যাগুলো দ্বিঘাত সমীকরণের সাহায্যে নির্ণয় কর।"],
 "ক) দশক স্থানীয় অঙ্ক = 9 − x\nমূল সংখ্যা = 10(9 − x) + x = 90 − 9x\nস্থান বিনিময়ের পর = 10x + (9 − x) = 9x + 9\nখ) (90 − 9x) − (9x + 9) = 27 ⇒ 81 − 18x = 27 ⇒ x = 3\nমূল সংখ্যা = 90 − 27 = 63\nগ) x(9 − x) = 18 ⇒ x² − 9x + 18 = 0 ⇒ (x − 3)(x − 6) = 0 ⇒ x = 3, 6\nএকক অঙ্ক 3 হলে সংখ্যা 63, একক অঙ্ক 6 হলে সংখ্যা 36\n∴ সম্ভাব্য সংখ্যা 63 ও 36"),
("একজন সাইকেল আরোহী 60 কিমি দূরের একটি স্থানে নির্দিষ্ট বেগে গিয়ে ঘণ্টায় 12 কিমি বেগে ফিরে আসেন। যাওয়া-আসায় তার মোট 9 ঘণ্টা সময় লাগে।",
 ["যাওয়ার বেগ x কিমি/ঘণ্টা ধরে সমীকরণ গঠন করে x নির্ণয় কর।","যাওয়ার সময় বেগ ঘণ্টায় 5 কিমি বেশি হলে 1 ঘণ্টা কম লাগত। এই তথ্য থেকে দ্বিঘাত সমীকরণ গঠন করে দেখাও যে, যাওয়ার বেগ ক এর সমান।","যাওয়া-আসার গড় বেগ নির্ণয় কর। যাওয়ার বেগ কত হলে যাওয়া-আসায় মোট 8 ঘণ্টা লাগত?"],
 "ক) যাওয়ার সময় = 60/x, ফেরার সময় = 60/12 = 5 ঘণ্টা\n60/x + 5 = 9 ⇒ 60/x = 4 ⇒ x = 15 কিমি/ঘণ্টা\nখ) 60/x − 60/(x + 5) = 1 ⇒ 60(x + 5) − 60x = x(x + 5)\n⇒ x² + 5x − 300 = 0 ⇒ (x + 20)(x − 15) = 0\nবেগ ঋণাত্মক নয় ⇒ x = 15 কিমি/ঘণ্টা, যা ক এর সমান\nগ) গড় বেগ = মোট দূরত্ব ÷ মোট সময় = 120 ÷ 9 = 40/3 ≈ 13.33 কিমি/ঘণ্টা\n60/v + 5 = 8 ⇒ 60/v = 3 ⇒ v = 20 কিমি/ঘণ্টা"),
]
items=[]
for i,(s_,p_,a_) in enumerate(CQ):
    assert len(p_)==3 and a_.count('ক)')==1 and a_.count('খ)')==1 and a_.count('গ)')==1
    items.append({'n':f'b{i+1}','ex':'সমন্বিত','stem':s_,'p':p_,'a':a_,'lv':'মধ্যম'})
json.dump(items,open(os.path.join(os.path.dirname(os.path.abspath(__file__)),'cq_c10_5.json'),'w'),ensure_ascii=False,indent=1); print('cq_c10_5',len(items))
